"""
# frmodel.py is a part of the HEPTAPOD package.
# Copyright (C) 2025 HEPTAPOD authors (see AUTHORS for details).
# HEPTAPOD is licensed under the GNU GPL v3 or later, see LICENSE for details.
# Please respect the MCnet Guidelines, see GUIDELINES for details.

Structured schema for a FeynRules ``.fr`` model file.

This is the shared representation produced by Lagrangian extraction and consumed
by the ``.fr`` generator (render.py). Design principle: STRUCTURE the regular,
error-prone blocks (M$Parameters, M$ClassesDescription, M$GaugeGroups,
M$Information, IndexRange) so an LLM never hand-writes their Mathematica syntax,
and CARRY the irregular parts (Lagrangian algebra, mixing blocks, NLO
bookkeeping) as verbatim Mathematica strings.

All numeric fields are strings so exact FeynRules syntax survives untouched:
rationals like ``-1/3``, decimals like ``1500.``, scientific ``2.5*^-3``.
"""

from __future__ import annotations

import re
from enum import Enum
from typing import Dict, List, Optional, Tuple, Union

from pydantic import BaseModel, model_validator

# A verbatim numeric string: "-1/3", "1500.", "2.5*^-3", "Internal", "Automatic".
NumberStr = str

_OPEN = {"(": ")", "[": "]", "{": "}"}
_CLOSE = {v: k for k, v in _OPEN.items()}


def unbalanced(text: str) -> Optional[str]:
    """Why ``text`` has unbalanced brackets, or None when it is balanced.

    Mathematica strings ("...") and comments ((* ... *), nested) are skipped. An
    unbalanced verbatim string renders into a .fr that FeynRules stops reading
    with "Unexpected end of file" or "Invalid syntax", long after the schema
    said OK.
    """
    stack: List[Tuple[str, int]] = []
    i, n, depth = 0, len(text), 0
    while i < n:
        c = text[i]
        if depth:                                  # inside a comment
            if text.startswith("(*", i):
                depth, i = depth + 1, i + 2
            elif text.startswith("*)", i):
                depth, i = depth - 1, i + 2
            else:
                i += 1
            continue
        if text.startswith("(*", i):
            depth, i = 1, i + 2
            continue
        if c == '"':                               # string literal
            i += 1
            while i < n and text[i] != '"':
                i += 2 if text[i] == "\\" else 1
            if i >= n:
                return "unterminated string literal"
            i += 1
            continue
        if c in _OPEN:
            stack.append((c, i))
        elif c in _CLOSE:
            if not stack or stack[-1][0] != _CLOSE[c]:
                ctx = text[max(0, i - 30):i + 1]
                return f"unexpected '{c}' at character {i} (...{ctx})"
            stack.pop()
        i += 1
    if depth:
        return "unterminated comment"
    if stack:
        c, j = stack[-1]
        ctx = text[j:j + 30]
        return f"'{c}' at character {j} is never closed ({ctx}...)"
    return None


def _require_balanced(text: Optional[str], where: str) -> None:
    if text:
        why = unbalanced(text)
        if why:
            raise ValueError(f"{where}: unbalanced brackets: {why}")


# Mass and width values FeynRules reads: a number, or Internal. The renderer
# also maps "Automatic" to a numeric placeholder. Anything else ("Auto",
# "External", a parameter name) aborts LoadModel with "Wrong width assignment"
# or "Wrong mass assignment", or leaks an undefined name into the UFO.
_MW_WORDS = {"Internal", "Automatic"}
_MW_FUNCS = {"Sqrt", "Pi"}


def check_mass_width_value(v: Optional[str], where: str) -> None:
    if v is None:
        return
    s = str(v).strip()
    if s in _MW_WORDS:
        return
    names = set(re.findall(r"[A-Za-z$][A-Za-z0-9$]*", s)) - _MW_FUNCS
    if re.search(r"[0-9.][eE][+-]?[0-9]", s):
        raise ValueError(
            f"{where}: value {s!r} uses e-notation, which Mathematica reads as a "
            "product with a symbol; write it as \"1.*^12\""
        )
    if names or not re.search(r"[0-9]", s) or unbalanced(s):
        raise ValueError(
            f"{where}: value {s!r} is not a number, \"Internal\" or \"Automatic\" "
            "(FeynRules rejects anything else, e.g. \"Auto\" or \"External\"); "
            "use a numeric string such as \"1500.\" or \"2.5*^-3\""
        )


class Rule(BaseModel):
    """One Mathematica replacement rule, e.g. ``CKM[1,2] -> Sin[cabi]``."""

    lhs: str
    rhs: str
    delayed: bool = False  # False -> "->", True -> ":>"

    def render(self) -> str:
        return f"{self.lhs} {':>' if self.delayed else '->'} {self.rhs}"

    @model_validator(mode="after")
    def _check(self) -> "Rule":
        _require_balanced(self.lhs, f"rule lhs {self.lhs[:40]!r}")
        _require_balanced(self.rhs, f"rule {self.lhs[:40]!r} rhs")
        return self


class ParamType(str, Enum):
    External = "External"
    Internal = "Internal"


class SpinType(str, Enum):
    S = "S"  # scalar
    F = "F"  # fermion
    V = "V"  # vector
    U = "U"  # ghost
    T = "T"  # tensor
    W = "W"  # Weyl fermion
    R = "R"  # spin-3/2
    RW = "RW"


class RangeKind(str, Enum):
    Unfold = "Unfold"
    NoUnfold = "NoUnfold"
    Range = "Range"


class PropType(str, Enum):
    Sine = "Sine"
    Straight = "Straight"
    ScalarDash = "ScalarDash"
    GhostDash = "GhostDash"
    Curly = "Curly"
    W = "W"
    C = "C"
    S = "S"
    D = "D"


class PropArrow(str, Enum):
    true = "True"
    false = "False"
    none = "None"
    forward = "Forward"


class ModelInfo(BaseModel):
    authors: List[str]
    version: str
    date: str
    institutions: List[str] = []
    emails: List[str] = []


class GaugeGroup(BaseModel):
    """A M$GaugeGroups entry. Omitted entirely by BSM add-on models."""

    name: str  # LHS symbol: U1Y, SU2L, SU3C
    abelian: bool
    gauge_boson: str
    coupling_constant: Optional[str] = None
    charge: Optional[str] = None  # required iff abelian
    structure_constant: Optional[str] = None  # required iff non-abelian
    symmetric_tensor: Optional[str] = None
    representations: List[Tuple[str, str]] = []  # [("T","Colour")] or many
    definitions: List[str] = []  # VERBATIM rule strings

    @model_validator(mode="after")
    def _check(self) -> "GaugeGroup":
        if self.abelian and not self.charge:
            raise ValueError(f"gauge group {self.name}: Abelian group needs charge")
        if not self.abelian and not self.structure_constant:
            raise ValueError(
                f"gauge group {self.name}: non-Abelian group needs structure_constant"
            )
        for d in self.definitions:
            _require_balanced(d, f"gauge group {self.name} definition")
        return self


class IndexDecl(BaseModel):
    name: str  # Colour, Generation, SU2W ...
    range_kind: RangeKind
    size: int  # Range[size]
    style_symbol: Optional[str] = None  # IndexStyle[name, style_symbol]


class Parameter(BaseModel):
    """A M$Parameters entry (LHS symbol of ``==``)."""

    name: str
    parameter_type: Optional[ParamType] = None
    value: Optional[NumberStr] = None  # scalar; tensors use value_rules
    value_rules: List[Rule] = []  # tensor Value -> { ... }
    complex: Optional[bool] = None  # ComplexParameter
    block_name: Optional[str] = None  # External only
    order_block: Optional[int] = None  # External SCALAR only
    interaction_order: Optional[Tuple[str, int]] = None  # -> {NP, 1}
    indices: List[str] = []  # non-empty => tensor
    definitions: List[Rule] = []
    parameter_name: Optional[str] = None
    tex: Optional[str] = None
    description: Optional[str] = None
    tensor_class: Optional[str] = None
    # tensor-only flags
    unitary: Optional[bool] = None
    hermitian: Optional[bool] = None
    orthogonal: Optional[bool] = None
    allow_summation: Optional[bool] = None

    @property
    def is_tensor(self) -> bool:
        return bool(self.indices)

    @model_validator(mode="after")
    def _check(self) -> "Parameter":
        _require_balanced(self.value, f"parameter {self.name} value")
        if self.is_tensor:
            if self.value is not None:
                raise ValueError(
                    f"parameter {self.name}: tensor uses value_rules, not scalar value"
                )
            if self.order_block is not None:
                raise ValueError(
                    f"parameter {self.name}: order_block forbidden on tensors"
                )
        exclusive = [f for f in (self.unitary, self.hermitian, self.orthogonal) if f]
        if len(exclusive) > 1:
            raise ValueError(
                f"parameter {self.name}: at most one of unitary/hermitian/orthogonal"
            )
        if (self.unitary or self.hermitian) and self.complex is False:
            raise ValueError(
                f"parameter {self.name}: unitary/hermitian require complex=True"
            )
        if self.orthogonal and self.complex is True:
            raise ValueError(f"parameter {self.name}: orthogonal must be real")
        if self.parameter_type == ParamType.External and self.complex is True:
            raise ValueError(
                f"parameter {self.name}: External params must be real "
                "(split into real/imag or make Internal)"
            )
        return self


class MassSpec(BaseModel):
    """Renders 0 | {sym} | {sym,val} | {sym,Internal} | {gen,{m1,v1},...}."""

    massless: bool = False  # -> literal 0
    sym: Optional[str] = None
    value: Optional[NumberStr] = None  # number | "Internal" | "Automatic" | None
    members: List[Tuple[str, Optional[NumberStr]]] = []  # multi-gen

    @model_validator(mode="after")
    def _check(self) -> "MassSpec":
        if not self.massless and not self.sym:
            raise ValueError("MassSpec needs massless=True or a sym")
        check_mass_width_value(self.value, f"mass/width {self.sym}")
        for sub, val in self.members:
            check_mass_width_value(val, f"mass/width member {sub}")
        return self


class ParticleClass(BaseModel):
    """A M$ClassesDescription entry, e.g. ``S[100] == {...}``."""

    spin_type: SpinType
    class_index: int  # the n in S[100]
    class_name: str
    self_conjugate: bool
    indices: List[str] = []  # -> Index[...] wrapped
    flavor_index: Optional[str] = None  # BARE name
    class_members: List[str] = []
    mass: Optional[MassSpec] = None
    width: Optional[MassSpec] = None
    quantum_numbers: Dict[str, NumberStr] = {}  # values are strings -> preserve -1/3
    pdg: Optional[Union[int, List[int]]] = None
    particle_name: Optional[Union[str, List[str]]] = None
    antiparticle_name: Optional[Union[str, List[str]]] = None
    full_name: Optional[Union[str, List[str]]] = None
    propagator_label: Optional[Union[str, List[str]]] = None
    propagator_type: Optional[PropType] = None
    propagator_arrow: Optional[PropArrow] = None
    unphysical: bool = False
    definitions: List[str] = []  # VERBATIM Mathematica rule strings
    ghost: Optional[str] = None  # U[n] only
    goldstone: Optional[str] = None  # S[n] only
    weyl_components: List[str] = []
    majorana_phase: Optional[str] = None
    chirality: Optional[str] = None

    @property
    def class_label(self) -> str:
        return f"{self.spin_type.value}[{self.class_index}]"

    @model_validator(mode="after")
    def _check(self) -> "ParticleClass":
        if self.unphysical:
            if self.mass or self.pdg:
                raise ValueError(
                    f"particle {self.class_name}: unphysical fields omit mass/pdg"
                )
            if not self.definitions:
                raise ValueError(
                    f"particle {self.class_name}: unphysical fields require definitions"
                )
        if len(self.class_members) > 1:
            if not self.flavor_index:
                raise ValueError(
                    f"particle {self.class_name}: multi-member class needs flavor_index"
                )
            n = len(self.class_members)
            for lst in (
                self.pdg,
                self.particle_name,
                self.antiparticle_name,
                self.full_name,
            ):
                if isinstance(lst, list) and len(lst) != n:
                    raise ValueError(
                        f"particle {self.class_name}: list length must equal "
                        f"member count ({n})"
                    )
        charged = {k: v for k, v in self.quantum_numbers.items()
                   if str(v).strip() not in ("0", "0.", "0/1")}
        if self.self_conjugate and charged:
            raise ValueError(
                f"particle {self.class_name}: a self_conjugate=true (real or Majorana) "
                f"field cannot carry a charge (got {charged}). Make the field complex "
                "(self_conjugate=false) if it is charged, or drop the charge"
            )
        for d in self.definitions:
            _require_balanced(d, f"particle {self.class_name} definition")
        if self.spin_type == SpinType.U:
            if self.self_conjugate:
                raise ValueError(
                    f"particle {self.class_name}: ghosts must be self_conjugate=False"
                )
            if not self.ghost:
                raise ValueError(f"particle {self.class_name}: ghost needs ghost=<boson>")
        return self


class LagrangianTerm(BaseModel):
    name: str  # LHS symbol
    expression: str  # VERBATIM Mathematica RHS
    delayed: bool = False  # True -> ":=", False -> "="

    @model_validator(mode="after")
    def _check(self) -> "LagrangianTerm":
        _require_balanced(self.expression, f"lagrangian term {self.name}")
        return self


def _references(text: str, name: str) -> bool:
    """True if ``name`` appears in ``text`` as a whole Mathematica token."""
    if not text:
        return False
    return re.search(rf"(?<![A-Za-z0-9$]){re.escape(name)}(?![A-Za-z0-9$])", text) is not None


def _param_refs(p: Parameter, names: set) -> set:
    """Names of other parameters referenced by ``p``'s value/rules/definitions."""
    texts: List[str] = []
    if p.value:
        texts.append(p.value)
    for r in p.value_rules:
        texts.append(r.rhs)
    for r in p.definitions:
        texts.append(r.rhs)
    blob = " ".join(texts)
    return {n for n in names if n != p.name and _references(blob, n)}


def topo_sort_parameters(params: List[Parameter]) -> List[Parameter]:
    """Order parameters so each is defined before others that reference it.

    Stable (preserves input order among independent params). Raises on a
    dependency cycle.
    """
    names = {p.name for p in params}
    deps = {p.name: _param_refs(p, names) for p in params}
    by_name = {p.name: p for p in params}

    ordered: List[Parameter] = []
    emitted: set = set()
    remaining = [p.name for p in params]  # preserve input order

    while remaining:
        progressed = False
        still: List[str] = []
        for n in remaining:
            if deps[n] <= emitted:
                ordered.append(by_name[n])
                emitted.add(n)
                progressed = True
            else:
                still.append(n)
        remaining = still
        if not progressed:
            raise ValueError(
                f"cyclic parameter dependency among: {sorted(remaining)}"
            )
    return ordered


_INDEX_SIZE = {"Generation": 3, "Colour": 3, "Gluon": 8, "SU2D": 2, "SU2W": 3}


def _block_entries(p: Parameter, sizes: Dict[str, int]) -> set:
    """The LHA entries (index tuples) an External parameter occupies in its block."""
    if not p.is_tensor:
        return {(p.order_block,)} if p.order_block is not None else set()
    entries = set()
    for r in p.value_rules:
        m = re.fullmatch(rf"\s*{re.escape(p.name)}\s*\[([0-9,\s]+)\]\s*", r.lhs)
        if m:
            entries.add(tuple(int(x) for x in m.group(1).split(",")))
    if entries:
        return entries
    ranges = [range(1, sizes.get(i, 3) + 1) for i in p.indices]
    out = {()}
    for rg in ranges:
        out = {e + (k,) for e in out for k in rg}
    return out


def _check_block_collisions(params: List[Parameter], sizes: Dict[str, int]) -> None:
    """External parameters that share an LHA block must not share an entry.

    FeynRules files an External tensor's entries under (block, i, j) and a
    scalar under (block, OrderBlock). Two parameters on one entry leave the UFO
    with one name defined twice, and MadGraph rejects the model ("name VLq1x1
    define multiple time"). Tensors of different rank in one block do not
    collide: GeneralU1's yN[i] and ynu[i,j] share a block and import cleanly.
    """
    by_block: Dict[str, List[Parameter]] = {}
    for p in params:
        if p.parameter_type == ParamType.External and p.block_name:
            by_block.setdefault(p.block_name, []).append(p)
    for block, ps in by_block.items():
        owner: Dict[tuple, str] = {}
        for p in ps:
            for e in sorted(_block_entries(p, sizes)):
                if e in owner and owner[e] != p.name:
                    raise ValueError(
                        f"External parameters {owner[e]} and {p.name} both occupy "
                        f"block {block!r} entry {list(e)}: the UFO would define one "
                        "name twice. Give one of them its own block_name (or, for "
                        "scalars, its own order_block)"
                    )
                owner[e] = p.name


class FeynRulesModel(BaseModel):
    """A complete FeynRules ``.fr`` model, ready to render."""

    model_name: str
    info: ModelInfo
    interaction_order_hierarchy: List[Tuple[str, int]] = []
    interaction_order_limit: List[Tuple[str, int]] = []
    feynman_gauge: Optional[bool] = None
    vevs: List[Tuple[str, str]] = []  # {{Phi[..], vev}}
    gauge_groups: List[GaugeGroup] = []
    index_decls: List[IndexDecl] = []
    parameters: List[Parameter] = []
    particles: List[ParticleClass] = []
    gauge_xi: List[Tuple[str, str]] = []  # (V[3], "GaugeXi[W]")
    lagrangian_terms: List[LagrangianTerm] = []
    # Verbatim escape hatches for irregular constructs (FR$LoopSwitches,
    # Mix[...] mixing blocks, SUSY superfields, ...).
    raw_preamble: List[str] = []  # emitted after M$Information, before IndexRange
    raw_blocks: List[str] = []  # emitted just before Lagrangian terms

    @model_validator(mode="after")
    def _check(self) -> "FeynRulesModel":
        labels = [p.class_label for p in self.particles]
        if len(labels) != len(set(labels)):
            dupes = sorted({x for x in labels if labels.count(x) > 1})
            raise ValueError(f"duplicate ParticleClass labels: {dupes}")

        # Lorentz/Spin* are FeynRules built-ins. Colour/Gluon/Generation/SU2D/
        # SU2W are declared by SM.fr, which every BSM add-on is loaded on top of,
        # so they need no IndexRange in the add-on itself (matches the reference
        # S1_LQ_RR.fr, which uses Index[Colour] without redeclaring it). Only
        # genuinely new indices must be declared in index_decls.
        builtin = {
            "Lorentz", "Spin", "Spin1", "Spin2",
            "Colour", "Gluon", "Generation", "SU2D", "SU2W",
        }
        declared = {d.name for d in self.index_decls} | builtin
        used = {i for p in self.particles for i in p.indices} | {
            i for prm in self.parameters for i in prm.indices
        }
        missing = used - declared
        if missing:
            raise ValueError(
                f"indices used without an IndexRange declaration: {sorted(missing)}"
            )

        for i, raw in enumerate(self.raw_preamble):
            _require_balanced(raw, f"raw_preamble[{i}]")
        for i, raw in enumerate(self.raw_blocks):
            _require_balanced(raw, f"raw_blocks[{i}]")

        names = [p.name for p in self.parameters]
        dupes = sorted({x for x in names if names.count(x) > 1})
        if dupes:
            raise ValueError(f"duplicate parameter names: {dupes}")
        sizes = dict(_INDEX_SIZE, **{d.name: d.size for d in self.index_decls})
        _check_block_collisions(self.parameters, sizes)

        self.parameters = topo_sort_parameters(self.parameters)
        return self

#!/usr/bin/env python3
"""Deterministic lints for an agent-written FeynRules add-on (.fr) file.

Every rule encodes one construct that broke a compile, a FeynRules check or a
MadGraph import in the benchmark (prompt_addendum_v3.txt rules 9-15 and the
repair-loop taxonomy). A lint runs in milliseconds on the text; the compile it
predicts takes up to 900 s.

Each finding carries the STAGE it predicts:
  compile  - FeynRules will not load or will not finish the model
  checks   - the model loads but a consistency check fails
  mg5      - the UFO is written but MadGraph rejects it
  harness  - the validation harness cannot pick the total Lagrangian
  warn     - FeynRules warns; the run may still pass

Library: ``lint_text(text) -> list[Finding]``. CLI: ``fr_lint.py file.fr``.
"""

from __future__ import annotations

import json
import re
import sys
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Dict, List, Optional, Set

HEPTAPOD = Path.home() / "Documents/Github/heptapod"
SM_FR = HEPTAPOD / "tools/feynrules/test_files/models/SM.fr"

# Mathematica built-ins and FeynRules symbols a class, parameter or index must
# not be named after (rule 10).
FR_SYMBOLS = {"HC", "CC", "FS", "DC", "del", "Eps", "Ga", "ProjP", "ProjM", "T",
              "Sig", "PauliSigma", "IndexDelta", "ME", "Index", "Indices", "Mass",
              "Width", "Value", "Unphysical", "Abelian"}
PROTECTED = {"N", "C", "D", "E", "I", "K", "O", "Pi", "Gamma", "Beta", "Zeta",
             "Sqrt", "Exp", "Log", "Sin", "Cos", "Tan", "Re", "Im", "Conjugate",
             "Sum", "Block", "Module", "Table", "If", "Which"}

# Names SM.fr declares: classes, class members, parameters, gauge groups, indices.
_SM_TEXT = SM_FR.read_text() if SM_FR.is_file() else ""
SM_CLASSES: Set[str] = set(re.findall(r"ClassName\s*->\s*(\w+)", _SM_TEXT))
SM_MEMBERS: Set[str] = set()
for _m in re.findall(r"ClassMembers\s*->\s*\{([^}]*)\}", _SM_TEXT):
    SM_MEMBERS |= {x.strip() for x in _m.split(",") if x.strip()}
_i = _SM_TEXT.find("M$Parameters")
SM_PARAMS: Set[str] = set(re.findall(r"^\s*(\w+)\s*==\s*\{", _SM_TEXT[_i:], re.M)) if _i >= 0 else set()
SM_GAUGE = {"U1Y", "SU2L", "SU3C"}
SM_INDICES = {"Generation", "Colour", "Gluon", "SU2D", "SU2W", "Lorentz", "Spin",
              "Spin1", "Spin2", "Sextet"}
SM_FIELDS_ALL = SM_CLASSES | SM_MEMBERS | {c + "bar" for c in SM_CLASSES | SM_MEMBERS}
SM_MASSES = {"MZ", "MW", "MH", "Me", "MMU", "MTA", "MU", "MC", "MT", "MD", "MS", "MB",
             "WZ", "WW", "WH", "WT"}

FR_BUILTINS = {"HC", "CC", "FS", "DC", "del", "Eps", "Ga", "ProjP", "ProjM", "T",
               "PauliSigma", "IndexDelta", "ME", "Sqrt", "Exp", "Log", "Sin", "Cos",
               "Tan", "I", "Pi", "Sum", "Block", "Module", "ExpandIndices",
               "FlavorExpand", "True", "False", "bar", "anti", "left", "right",
               "Conjugate", "Re", "Im", "Abs", "Sig", "Ta", "T6", "K6", "K6bar",
               "K3", "K3bar", "f", "dSUN", "Dot", "Times", "Plus", "Power",
               "Automatic", "Internal", "External", "Unfold", "NoUnfold", "Range",
               "Index", "Lorentz", "Spin", "Colour", "Gluon", "Generation",
               "SU2D", "SU2W", "Sextet", "IndexStyle", "MakeIdenticalFermions",
               "Expand", "Simplify", "ProjPlus", "ProjMinus", "FR$", "vev"}


@dataclass
class Finding:
    rule: str
    stage: str  # compile | checks | mg5 | harness | warn
    message: str
    line: Optional[int] = None


# ------------------------------------------------------------------ parsing

def strip_comments(text: str) -> str:
    out, depth, i = [], 0, 0
    while i < len(text):
        if text.startswith("(*", i):
            depth += 1
            i += 2
            continue
        if text.startswith("*)", i) and depth:
            depth -= 1
            i += 2
            continue
        if depth == 0:
            out.append(text[i])
        elif text[i] == "\n":
            out.append("\n")
        i += 1
    return "".join(out)


def _matching(text: str, open_idx: int) -> int:
    depth = 0
    pairs = {"{": "}", "[": "]", "(": ")"}
    closes = set(pairs.values())
    for j in range(open_idx, len(text)):
        ch = text[j]
        if ch in pairs:
            depth += 1
        elif ch in closes:
            depth -= 1
            if depth == 0:
                return j
    return len(text) - 1


def _block(text: str, name: str) -> str:
    m = re.search(rf"M\${name}\s*=\s*\{{", text)
    if not m:
        return ""
    end = _matching(text, m.end() - 1)
    return text[m.end():end]


def _entries(block: str) -> List[Dict]:
    """Top-level `Head == { ... }` entries of a M$ block."""
    out = []
    for m in re.finditer(r"(\w+(?:\[\s*\d+\s*\])?)\s*==\s*\{", block):
        end = _matching(block, m.end() - 1)
        body = block[m.end():end]
        out.append({"head": m.group(1), "body": body, "pos": m.start()})
    return out


def _prop(body: str, key: str) -> Optional[str]:
    m = re.search(rf"\b{key}\s*->\s*", body)
    if not m:
        return None
    rest = body[m.end():]
    if rest.startswith("{"):
        return rest[: _matching(rest, 0) + 1]
    mm = re.match(r"[^,}\n]+", rest)
    return mm.group(0).strip() if mm else None


def _is_kin_name(name: str) -> bool:
    return bool(re.search(r"kin|Kin|KIN|free|Free|Gauge|gauge", name))


def term_defs(text: str) -> List[Dict]:
    starts = [(m.group(1), m.start()) for m in re.finditer(r"^(L\w+)\s*:?=", text, re.M)]
    stops = [m.start() for m in re.finditer(r"^(?:M\$\w+\s*=|L\w+\s*:?=|\w+\s*=\s*\{)", text, re.M)]
    out = []
    for name, s in starts:
        e = min([x for x in stops if x > s] + [len(text)])
        out.append({"name": name, "body": text[s:e], "line": text[:s].count("\n") + 1})
    return out


def _line_of(text: str, needle: str) -> Optional[int]:
    i = text.find(needle)
    return text[:i].count("\n") + 1 if i >= 0 else None


# -------------------------------------------------------------------- lints

def lint_text(raw: str) -> List[Finding]:
    text = strip_comments(raw)
    F: List[Finding] = []
    classes = _entries(_block(text, "ClassesDescription"))
    params = _entries(_block(text, "Parameters"))
    terms = term_defs(text)
    term_names = {t["name"] for t in terms}
    term_bodies = "\n".join(t["body"] for t in terms)

    class_names, class_idx = {}, {}
    for c in classes:
        cn = _prop(c["body"], "ClassName")
        if cn:
            class_names[cn] = c
            mi = re.match(r"(\w+)\[\s*(\d+)\s*\]", c["head"])
            if mi:
                class_idx[cn] = (mi.group(1), int(mi.group(2)))
    param_names = {p["head"]: p for p in params}
    index_decls = dict(re.findall(r"IndexRange\[\s*Index\[(\w+)\]\s*\]\s*=\s*([^;\n]+)", text))

    # --- rule 10: names -------------------------------------------------
    for name in list(class_names) + list(param_names) + list(index_decls):
        if name in FR_SYMBOLS:
            F.append(Finding("feynrules_symbol_name", "compile",
                             f"`{name}` is a FeynRules symbol", _line_of(text, name)))
        elif name in PROTECTED:
            F.append(Finding("protected_name", "warn",
                             f"`{name}` is a Mathematica built-in (loads with a warning; renaming is safer)",
                             _line_of(text, name)))
    for name in class_names:
        if name in SM_CLASSES or name in SM_MEMBERS:
            F.append(Finding("sm_class_redeclared", "warn",
                             f"class `{name}` is already declared by SM.fr (doubly-defined class)",
                             _line_of(text, f"ClassName -> {name}")))
    for name in param_names:
        if name in SM_PARAMS or name in SM_MASSES:
            F.append(Finding("sm_parameter_redeclared", "warn",
                             f"parameter `{name}` is already declared by SM.fr", _line_of(text, name)))
    for cn, c in class_names.items():
        for key in ("ParticleName", "AntiParticleName"):
            v = _prop(c["body"], key)
            names = re.findall(r'"([^"]*)"', v) if v else []
            if v and any(re.search(r"[\'`\s!@#%^&*()=\[\]{}|\\;:<>?/,]", nm) for nm in names):
                F.append(Finding("bad_particle_name", "mg5",
                                 f"class `{cn}`: {key} {v} is not a valid UFO identifier", _line_of(text, v)))
        if cn in class_idx and class_idx[cn][1] < 100:
            F.append(Finding("low_class_index", "warn",
                             f"class `{cn}` uses index {class_idx[cn][0]}[{class_idx[cn][1]}]; SM.fr uses the low indices",
                             _line_of(text, c["head"])))
        for m in re.finditer(r"ClassMembers\s*->\s*\{([^}]*)\}", c["body"]):
            for mem in [x.strip() for x in m.group(1).split(",") if x.strip()]:
                if mem in SM_MEMBERS or mem in SM_CLASSES:
                    F.append(Finding("sm_member_redeclared", "compile",
                                     f"class member `{mem}` of `{cn}` collides with an SM.fr name",
                                     _line_of(text, mem)))
    if "$" in re.sub(r"M\$\w+", "", text):
        for m in re.finditer(r"\b\w*\$\w*", text):
            if not re.match(r"^(M|MR|FR)\$", m.group(0)):
                F.append(Finding("dollar_in_name", "mg5", f"`{m.group(0)}` contains `$` (invalid Python)",
                                 text[:m.start()].count("\n") + 1))
                break

    # --- rule 11: interaction orders --------------------------------------
    hierarchy = _block(text, "InteractionOrderHierarchy")
    orders_declared = set(re.findall(r"\{\s*(\w+)\s*,\s*-?\d+\s*\}", hierarchy))
    for pn, p in param_names.items():
        body = p["body"]
        ptype = (_prop(body, "ParameterType") or "External").strip()
        io = _prop(body, "InteractionOrder")
        used = re.search(rf"\b{re.escape(pn)}\b", term_bodies) is not None
        is_mass = any(re.search(rf"Mass\s*->\s*\{{\s*{re.escape(pn)}\b", c["body"]) or
                      re.search(rf"Width\s*->\s*\{{\s*{re.escape(pn)}\b", c["body"])
                      for c in classes) or re.match(r"^(M|W)[A-Z]", pn) and not io
        if io:
            oname = re.findall(r"\{\s*(\w+)\s*,", io)
            for o in oname:
                if o not in orders_declared and o not in ("QCD", "QED"):
                    F.append(Finding("order_not_in_hierarchy", "warn",
                                     f"parameter `{pn}` uses InteractionOrder `{o}` not listed in M$InteractionOrderHierarchy",
                                     _line_of(text, pn)))
    ordered = {pn for pn, p in param_names.items() if _prop(p["body"], "InteractionOrder")}
    internal = {pn for pn, p in param_names.items()
                if (_prop(p["body"], "ParameterType") or "External").strip() == "Internal"}
    # an Internal parameter inherits the orders of the parameters in its Value
    for pn in list(internal):
        val = _prop(param_names[pn]["body"], "Value") or ""
        if any(re.search(rf"\b{re.escape(o)}\b", val) for o in ordered):
            ordered.add(pn)
    for t in terms:
        if _is_kin_name(t["name"]):
            continue
        used_params = {pn for pn in param_names if re.search(rf"\b{re.escape(pn)}\b", t["body"])}
        sm_couplings = {"ee", "gw", "gs", "g1", "yl", "yu", "yd", "lam", "CKM"}
        if used_params and not (used_params & ordered) and not \
                any(re.search(rf"\b{c}\b", t["body"]) for c in sm_couplings) and \
                not any(re.search(rf"\b(DC|FS)\[", t["body"]) for _ in [0]):
            F.append(Finding("missing_interaction_order", "mg5",
                             f"`{t['name']}`: none of its parameters ({', '.join(sorted(used_params))}) carries an InteractionOrder",
                             t["line"]))

    # --- rule 12: pattern rules on tensor parameters -----------------------
    for pn, p in param_names.items():
        if re.search(r"\w+\[[^\]]*_[^\]]*\]\s*:?->", p["body"]) or "_?NumericQ" in p["body"]:
            F.append(Finding("pattern_rule_definition", "mg5",
                             f"parameter `{pn}` uses a pattern rule in Definitions/Value; FeynRules exports it verbatim as a UFO name",
                             _line_of(text, pn)))
    for cn, c in class_names.items():
        d = _prop(c["body"], "Definitions") or ""
        if re.search(r"\w+\[[^\]]*_[^\]]*\]\s*:>", d) and not re.search(r"\w+\[[^\]]*_\s*[,\]]", d):
            pass  # `X[mu_] :> ...` is the normal FeynRules idiom; leave it

    # --- rule 13: explicit indices ------------------------------------------
    for t in terms:
        b = t["body"]
        for m in re.finditer(r"DC\[\s*(\w+)\[([^\]]*)\]\s*,", b):
            fld = m.group(1)
            c = class_names.get(fld)
            idx = (_prop(c["body"], "Indices") or "") if c else ""
            if c and re.search(r"Colour|Sextet|Gluon|Octet|Col", idx):
                F.append(Finding("explicit_index_in_dc", "compile",
                                 f"`{t['name']}`: covariant derivative on `{fld}` with an explicit colour-type index", t["line"]))
            else:
                F.append(Finding("explicit_index_in_dc", "warn",
                                 f"`{t['name']}`: covariant derivative on an explicitly indexed field `{fld}`", t["line"]))
            break
        if re.search(r"Index\[\s*Generation\s*,\s*\w+\s*\]\s*,\s*Index\[\s*Generation", b) or \
                re.search(r"\w+\[\s*Generation\s*,\s*\w+\s*\]", b):
            F.append(Finding("nested_generation_index", "compile",
                             f"`{t['name']}`: nested generation index", t["line"]))
        m = re.search(r"\b(\w+)\[\s*(ff\d?|gen\d?|ii\d?)\s*,\s*(ff\d?|gen\d?|jj\d?)\s*\]\s*\w+bar\[", b)
        if m and m.group(1) in param_names:
            F.append(Finding("explicit_flavour_sum", "mg5",
                             f"`{t['name']}`: flavour matrix `{m.group(1)}` with explicit generation indices instead of matrix form",
                             t["line"]))

    # --- rule 14: one declared total ---------------------------------------
    roots = []
    for t in terms:
        if not any(re.search(rf"\b{t['name']}\b", u["body"]) for u in terms if u is not t):
            roots.append(t["name"])
    if terms and not roots:
        F.append(Finding("no_total_lagrangian", "harness", "no Lagrangian symbol is a root (circular or empty)", None))
    elif len(roots) > 1:
        F.append(Finding("ambiguous_total", "harness",
                         f"{len(roots)} root Lagrangian symbols: {', '.join(roots)}", None))
    elif roots and roots[0] not in ("LTotal", "LTot", "LFull", "LBSM", "LNP", "Lag", "LagTot"):
        F.append(Finding("total_not_named_ltotal", "warn", f"the single root is `{roots[0]}`, not LTotal", None))
    field_tokens = set(class_names) | {c + "bar" for c in class_names} | SM_FIELDS_ALL
    for c in classes:
        for m in re.finditer(r"ClassMembers\s*->\s*\{([^}]*)\}", c["body"]):
            field_tokens |= {x.strip() for x in m.group(1).split(",") if x.strip()}
    for t in terms:
        rhs = t["body"].split("=", 1)[-1]
        if re.search(r"\bL\w+\b", rhs) and any(re.search(rf"\b{u['name']}\b", rhs) for u in terms if u is not t):
            continue  # a sum of other terms
        if not any(re.search(rf"\b{re.escape(f)}\b", rhs) for f in field_tokens):
            F.append(Finding("fieldless_term", "mg5", f"`{t['name']}` contains no field", t["line"]))

    # --- rule 15: declarations -----------------------------------------------
    for cn, c in class_names.items():
        sc = (_prop(c["body"], "SelfConjugate") or "").strip()
        qn = _prop(c["body"], "QuantumNumbers")
        if sc == "True" and qn and re.search(r"->\s*-?[1-9]", qn):
            F.append(Finding("selfconjugate_with_qn", "warn",
                             f"class `{cn}` is SelfConjugate and carries QuantumNumbers {qn}",
                             _line_of(text, f"ClassName -> {cn}")))
        if sc == "True" and _prop(c["body"], "AntiParticleName"):
            pass
    # Majorana mass normalisation
    for cn, c in class_names.items():
        if (_prop(c["body"], "SelfConjugate") or "").strip() == "True" and c["head"].startswith("F"):
            mm = re.search(r"Mass\s*->\s*\{\s*(\w+)", c["body"])
            if not mm:
                continue
            M = mm.group(1)
            pat = re.compile(rf"(-?\s*(?:1/2|0\.5|\(1/2\))?\s*\*?\s*{M}\b[^;]{{0,40}}{cn}bar\s*\.\s*{cn}\b)")
            for t in terms:
                for hit in pat.finditer(t["body"]):
                    if not re.search(r"1/2|0\.5", hit.group(1)):
                        F.append(Finding("majorana_mass_no_half", "checks",
                                         f"`{t['name']}`: Majorana mass term for `{cn}` without the 1/2",
                                         t["line"]))
    # undeclared symbols in terms (conservative: capitalised identifiers used as fields)
    declared = set(class_names) | {c + "bar" for c in class_names} | set(param_names) | \
        SM_FIELDS_ALL | SM_PARAMS | SM_MASSES | FR_BUILTINS | set(term_names) | set(index_decls) | \
        {"If", "Which", "Table", "KroneckerDelta", "Transpose", "Inverse", "ArcTan", "Sec", "Csc",
         "Cot", "Abs", "MatrixExp", "DiagonalMatrix", "IdentityMatrix", "Sum", "Product"}
    for c in classes:
        for key in ("Mass", "Width"):
            v = _prop(c["body"], key) or ""
            declared |= set(re.findall(r"\b([A-Za-z]\w*)\b", v)) - {"Internal", "External", "Automatic"}
    for c in classes:
        for m in re.finditer(r"ClassMembers\s*->\s*\{([^}]*)\}", c["body"]):
            for mem in [x.strip() for x in m.group(1).split(",") if x.strip()]:
                declared |= {mem, mem + "bar"}
        for m in re.finditer(r"Unphysical\s*->\s*True", c["body"]):
            pass
    for t in terms:
        b = re.sub(r'"[^"]*"', "", t["body"])
        locals_ = set()
        for m in re.finditer(r"(?:Block|Module)\[\s*\{([^}]*)\}", b):
            locals_ |= {x.strip().split("=")[0].strip() for x in m.group(1).split(",")}
        for m in re.finditer(r"\b([A-Za-z]\w*)\b", b):
            s = m.group(1)
            if s in declared or s in locals_ or s == t["name"] or len(s) < 2:
                continue
            if re.match(r"^(mu|nu|rho|sig|la|lam|al|be|sp|ss|ii|jj|kk|ll|ff|gg|cc|aa|bb|tt|rr|xx|yy|zz)\d*$", s):
                continue
            if s in ("ExpandIndices", "FlavorExpand", "Index", "Sqrt", "HC"):
                continue
            if s[0].isupper() and re.search(rf"\b{re.escape(s)}\s*[\[.]", b):
                F.append(Finding("undeclared_symbol", "warn",
                                 f"`{t['name']}` uses `{s}` which is neither declared here nor by SM.fr",
                                 t["line"]))
                break

    # --- rule 9: non-fundamental colour representations -----------------------
    for iname, rng in index_decls.items():
        if re.search(r"Range\[\s*6\s*\]", rng) and "AddGaugeRepresentation" not in text:
            F.append(Finding("sextet_without_representation", "warn",
                             f"index `{iname}` has range 6 but there is no AddGaugeRepresentation", _line_of(text, iname)))

    # --- mass mixing written into Definitions (the dominant check failure) ----
    phys_new = {cn for cn, c in class_names.items() if (_prop(c["body"], "Unphysical") or "").strip() != "True"}
    for cn, c in class_names.items():
        d = _prop(c["body"], "Definitions") or ""
        if not d:
            continue
        fields_in = {s for s in re.findall(r"\b([A-Za-z]\w*)\b", d) if s in phys_new or s in SM_CLASSES}
        fields_in -= {cn}
        if len(fields_in) >= 2 and re.search(r"\b(sa|ca|sin|cos|Sin|Cos|s\w*|c\w*)\w*\b", d):
            F.append(Finding("mixing_in_definitions", "checks",
                             f"class `{cn}` is defined as a mixture of {sorted(fields_in)}; the mass basis of the partner fields declared in SM.fr is unchanged",
                             _line_of(text, f"ClassName -> {cn}")))
    return F


def lint_file(path: str) -> List[Finding]:
    return lint_text(Path(path).read_text(errors="replace"))


if __name__ == "__main__":
    for p in sys.argv[1:]:
        fs = lint_file(p)
        print(json.dumps({"file": p, "findings": [asdict(f) for f in fs]}, indent=1))

