        &\phantom{12}+ i\dfrac{e}{s_w} \sum_{q \in Q\backslash\{+\frac{5}{3}\}} \left( \left(\hat{\Phi}^{q+1}\right)^\dagger \hat{\mathbbm{W}}_{q}^{q+1} \overset{\leftrightarrow}{\partial^\mu} \hat{\Phi}^q\right)W^+_\mu \,.
    \end{aligned}
\end{align}


with


\begin{align}
	\begin{aligned}
		\hat{\mathbbm{Z}}^q &\equiv W^q \mathbbm{Z}^q \left(W^{q}\right)^\dagger \text{ for } q \in Q \,, \\
		\hat{\mathbbm{W}}_q^{q+1} &\equiv W^{q+1} \mathbbm{W}_q^{q+1} \left(W^{q}\right)^\dagger \text{ for } q \in Q \backslash \left \{ +\frac{5}{3} \right \}\,. \\
	\end{aligned}
\end{align}


Explicitly, the matrices $\hat{\mathbbm{Z}}^q, \hat{\mathbbm{W}}_q^{q+1}$ are given by


\begin{align}
    \begin{aligned}
        \hat{\mathbbm{Z}}^{-1/3}& \approx \begin{pmatrix}
        \frac{1}{3}s_w^2 - \frac{v^2 \left|A_{1\tilde{2}} \right|^2}{4 \left(m^2_{1\tilde{2}}\right)^2} & -\frac{v A_{1\tilde{2}}^*}{2\sqrt{2} m_{1\tilde{2}}^2}& -\frac{v^2 A_{\tilde{2}3} A^*_{1 \tilde{2}}}{4m^2_{1\tilde{2}} m_{3\tilde{2}}^2} \\
        -\frac{v A_{1\tilde{2}}}{2 \sqrt{2} m_{1\tilde{2}}^2} & -\frac{1}{2} + \frac{1}{3} s_w^2 + \frac{v^2}{4}\left(\frac{\left | A_{1 \tilde{2}}\right |^2}{\left(m_{1\tilde{2}}^2\right)^2} +  \frac{\left | A_{\tilde{2}3}\right |^2}{\left(m_{3\tilde{2}}^2\right)^2} \right)& - \frac{v A_{\tilde{2}3}}{2 \sqrt{2} m_{3 \tilde{2}}^2} \\
        -\frac{v^2 A_{1\tilde{2}} A_{\tilde{2}3}^*}{4 m_{1 \tilde{2}}^2  m_{3\tilde{2}}^2} & - \frac{v A_{\tilde{2}3}^*}{2 \sqrt{2} m_{3 \tilde{2}}^2}& \frac{1}{3}s_w^2 - \frac{v^2 \left| A_{\tilde{2}3} \right|^2}{4 \left(m_{3 \tilde{2}}^2 \right)^2} \\
        \end{pmatrix}\,,\\ \rule{0pt}{3em}
\hat{\mathbbm{Z}}^{+2/3}& \approx \begin{pmatrix}
        -\frac{1}{2} - \frac{2}{3}s_w^2 & \frac{v^2Y_{2\tilde{2}}}{2 m_{2 \tilde{2}}^2} & 0 \\
        \frac{v^2Y^*_{2\tilde{2}}}{2 m_{2 \tilde{2}}^2} & \frac{1}{2}-\frac{2}{3}s_w^2 + \frac{ v^2 \left| A_{\tilde{2}3}\right|^2}{2\left(m_{\tilde{2}3}^2\right)^2} & -\frac{v A_{\tilde{2}3}}{2 m_{\tilde{2}3}^2} \\
        0 & -\frac{v A_{\tilde{2}3}^*}{2 m_{\tilde{2}3}^2} & 1 - \frac{2}{3} s_w^2 -  \frac{v^2 \left| A_{\tilde{2}3}\right|^2}{2 \left(m_{\tilde{2}3}^2 \right)^2} \\
        \end{pmatrix}\,, \\ \rule{0pt}{1em}
        \hat{\mathbbm{Z}}^{-4/3}&\approx\begin{pmatrix}
        \frac{4}{3}s_w^2 & -\frac{v^2 Y_{\tilde{1}3}^*}{\sqrt{2} m_{\tilde{1}3}^2}\\
        -\frac{v^2 Y_{\tilde{1}3}}{\sqrt{2}m_{\tilde{1}3}^2} & -1 + \frac{4}{3}s_w^2\\
        \end{pmatrix}\,, ~\hat{\mathbbm{Z}}^{+5/3} = \left(\frac{1}{2} - \frac{5}{3}s_w^2 \right)\,, \\
        \hat{\mathbbm{W}}^{+2/3}_{-1/3}& \approx \renewcommand*{\arraystretch}{2.0}  \begin{pmatrix}
	0 & \frac{v^2 Y_{2 \tilde{2}}}{2 m^2_{2 \tilde{2}}} & 0 \\
	\frac{v A_{1 \tilde{2}}}{\sqrt{2} m_{1 \tilde{2}}^2}& 1+ \frac{v^2}{4} \left( \frac{\left | A_{\tilde{2} 3} \right|^2}{\left(m_{\tilde{2} 3}^2\right)^2} -\frac{\left | A_{1\tilde{2}} \right|^2}{\left(m_{1\tilde{2}}^2\right)^2} \right)&  \frac{v A_{\tilde{2}3}}{\sqrt{2} m_{\tilde{2}3}^2}\\
	\frac{v^2}{\sqrt{2} m_{13}^2} \left(\frac{A_{1\tilde{2}}A_{\tilde{2}3}^*}{m^2_{\tilde{2}3}} - Y_{13}^* \right)&  0 & -\sqrt{2} + \frac{v^2\left| A_{\tilde{2}3}\right|^2}{2\sqrt{2} \left(m_{3 \tilde{2}}^2\right)^2}\\
        \end{pmatrix}\,,\\
        \hat{\mathbbm{W}}^{-1/3}_{-4/3}&\approx\begin{pmatrix}
        0 & \frac{v^2}{\sqrt{2} m_{13}^2} \left(Y_{13} + \frac{A_{\tilde{2}3}A_{1 \tilde{2}}^*}{m_{1\tilde{2}}^2} \right) \\
