                          \sqrt{2} Y_{\tilde{1}3}  & Y_3 - Y_{33} \\
                        \end{pmatrix}\,, 
        &\mathbb{\Gamma}^{+5/3} &= -v \Big(Y_2 + Y_{22} \Big) \,, \\
        \mathbb{\Lambda}^{-1/3} &= 
                -\phantom{v}\begin{pmatrix}
                   Y_1  & 0 & Y_{13}\\ 
                   0  & Y_{\tilde{2}} & 0\\ 
                    Y_{13}^{*} & 0 & Y_3
                \end{pmatrix} \,,
        &\mathbb{\Lambda}^{+2/3} &=
