    Unphysical       -> True,
    SelfConjugate    -> False,
    QuantumNumbers   -> {Y -> -1/3},
    Indices          -> {Index[Colour]},
    Definitions      -> {S1m13[cc_] :>   HC[W13mat[1,1]] 
                                         S1m13hat[cc] 
                                       + HC[W13mat[2,1]] 
                                         R2tm13hat[cc] 
                                       + HC[W13mat[3,1]] 
                                         S3m13hat[cc]}
},
