\subsection{Interactions with SM Fermions ($\mathcal{L}_{\text{f}}$)}
The interactions between the five scalar LQs and the SM fermions are listed below. $Y_{a}^{AB}{}$ with $a \in \{1, \tilde1, 2, \tilde2, 3 \}$ and $A,B \in \{L, R\}$ are arbitrary complex $3 \times 3$ matrices coupling LQs to a quark and a lepton. $Y_a^{Q,AA}$ with $a \in \left \{ 1, \tilde{1}, 2, \tilde{2}, 3 \right \}$ and $A \in \left \{ L, R\right \}$ couple LQs to two quarks. $Y_1^{Q, LL}$ is symmetric in flavour space (i.e. $Y_{1, ij}^{Q, LL}$ = $Y_{1, ji}^{Q, LL}$ ), $Y_{\tilde{1}}^{Q, RR}$ and $Y_{3}^{Q, LL}$ are anti-symmetric and $Y_{1}^{Q, RR}$ is again an arbitrary complex matrix. We omit the color indices whenever they just involve trivial contractions. 


\begin{equation}
    \renewcommand{\arraystretch}{1.5}
    \centering
    \begin{tabular}{c | c} 
         & $\mathcal{L}_{f}$ \\ \hline \rule{0pt}{2em}

    	\multirow{3}{*}{$\Phi_1$} & $Y_{1, ij}^{RR}\, \bar{u}^{\prime c}_i\ell^\prime_{j}\Phi_{1}^{\dagger} +Y_{1, ij}^{LL}\, \left(\bar{Q}_{i}^{\prime c \intercal} i\sigma_{2}L^\prime_{j}\right)\Phi_{1}^{\dagger}+\text{h.c.}$ \\ 
	\multirow{3}{*} &  $Y_{1, ij}^{Q, LL}\, \left(\bar{Q}^{\prime c \intercal}_{i, c_1} i\sigma_2 Q^\prime_{j, c_2}\right) \Phi_{1, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ 
	\multirow{3}{*} &  $Y_{1, ij}^{Q, RR} \bar{u}^{\prime c}_{i, c1} d^\prime_{j, c_2} \Phi_{1, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ \rule{0pt}{2em}

    	\multirow{2}{*}{$\Phi_{\tilde{1}}$} & $Y^{RR}_{\tilde{1}, ij}\, \bar{d}^{\prime c}_{i}\ell^\prime_{j}\Phi_{\tilde{1}}^{\dagger} +\text{h.c.}$ \\
	\multirow{2}{*} & $Y^{Q, RR}_{\tilde{1}, ij}\, \bar{u}^{\prime c}_{i, c_1} u^\prime_{j, c_2}\Phi_{\tilde{1}, c_3} \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\ \rule{0pt}{2em}

    	$\Phi_{2}$  & $Y_{2, ij}^{RL}\, \left(\Phi_{2}^\intercal \bar{u}^\prime_i i\sigma_2 L^\prime_{j} \right)+Y_{2, ij}^{LR}\, \left(\bar{Q}^{\prime \intercal}_i \ell^\prime_j\Phi_{2}\right)+\text{h.c.}$\\ \rule{0pt}{2em}

    	$\Phi_{\tilde{2}}$ & $Y_{\tilde{2}, ij}^{RL}\, \left(\Phi_{\tilde{2}}^\intercal \bar{d}^\prime_{i} i\sigma_2 L^\prime_{j}\right)+\text{h.c.}$ \\ \rule{0pt}{2em}

	\multirow{2}{*}{$\Phi_{3}$}  & $Y_{3, ij}^{LL}\, \left(\bar{Q}^{\prime c \intercal}_{i} i\sigma_{2}\left(\sigma\cdot\Phi_{3}\right)^{\dagger}L^\prime_{j}\right)+\text{h.c.}$ \\
	\multirow{2}{*} &  $Y^{Q, LL}_{3, ij}\, \left(\bar{Q}^{\prime c \intercal}_{i, c_1} i\sigma_2 \left(\sigma \cdot \Phi_{3, c_3}\right)Q^\prime_{j, c_2}\right) \epsilon^{c_1 c_2 c_3} +\text{h.c.}$ \\
    \end{tabular}
    \label{eq:LQ_yukawa}
\end{equation}


Again, we use brackets to indicate the $SU(2)_L$ contractions. Note that we stated the Lagrangian above before EW symmetry breaking using the weak eigenstates of the fermions (indicated by the prime). When going to the mass eigenbasis (after EW symmetry breaking), CKM matrix elements enter interactions involving left-handed down-type quarks according to Eq.~(\ref{eq:massEigenstates}). 







The charge-conjugate of a fermion field $\Psi$ is denoted as $\Psi^c$, where
\begin{equation}
\begin{aligned}
	\Psi^c &= C \bar{\Psi}^\intercal \,, \\
	\bar{\Psi}^c &= - \Psi^\intercal C^{-1}\,,
\end{aligned}
\label{eq:Cmatrix}
\end{equation}


with $C$ the charge conjugation matrix. A detailed description of our treatment of charge-conjugate SM fermions is given in \ref{sec:appendix}. 



\subsection{Triple LQ Interactions ($\mathcal{L}_{3 \Phi}$)}
Let us now turn to the LQ-LQ-LQ(-Higgs) interactions. In order to get a $SU(3)_c$ singlet, either three LQs or three anti-LQs have to be combined, since 


\begin{align}
    \begin{aligned}
    3 \otimes 3 \otimes 3 &= 1 \oplus 8 \oplus 8 \oplus 10 \\
    \overline{3} \otimes \overline{3} \otimes \overline{3} &= 1 \oplus 8 \oplus 8 \oplus \overline{10}
    \end{aligned}
\end{align}


are the only tensor products of three SU(3) (anti-)triplets $3, \overline{3}$ that contain a singlet. Regarding the hypercharge $Y$, one finds the possible combinations listed in Table~\ref{tab:triple}. 


\begin{table}[t]
    \renewcommand{\arraystretch}{1.2}
    \begin{center}
        \begin{tabular}{rr|c c c c c c c }
            & & \multicolumn{7}{c}{LQ Fields (and their $Y$)}\\
            & & $\Phi_1$ & $\Phi_{\tilde{1}}$ & $\Phi_2$ & $\Phi_{\tilde{2}}$ & $\Phi_{3}$ & $H$ & $H^\dagger$ \\ [0.5ex] 
            & & $-\frac{1}{3}$ & $-\frac{4}{3}$ & $\frac{7}{6}$ & $\frac{1}{6}$ & $-\frac{1}{3}$ & $\frac{1}{2}$ & $-\frac{1}{2}$ \\ [0.7ex]
            \cline{1-9}
            \multicolumn{1}{ c  }{\multirow{12}{*}{ \rotatebox[origin=c]{90}{Interaction Terms}} } & \multicolumn{1}{ r|  }{$Y_{112}$ } & 2 & 0 & 1 & 0 & 0 & 0 & 1 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{11\tilde2}$ } & 2 & 0 & 0 & 1 & 0 & 1 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{1\tilde12}$ } & 1 & 1 & 1 & 0 & 0 & 1 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{123}$ } & 1 & 0 & 1 & 0 & 1 & 0 & 1 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$A_{1\tilde2\tilde2}$ } & 1 & 0 & 0 & 2 & 0 & 0 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{1\tilde23}$ } & 1 & 0 & 0 & 1 & 1 & 1 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$A_{\tilde12\tilde2}$ } & 0 & 1 & 1 & 1 & 0 & 0 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{\tilde123}$ } & 0 & 1 & 1 & 0 & 1 & 1 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{233}$ } & 0 & 0 & 1 & 0 & 2 & 0 & 1 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{\tilde2 \tilde2 \tilde2}$ } & 0 & 0 & 0 & 3 & 0 & 0 & 1 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$A_{\tilde2 \tilde2 3}$ } & 0 & 0 & 0 & 2 & 1 & 0 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{\tilde2 33}$ } & 0 & 0 & 0 & 1 & 2 & 1 & 0 \\
        \end{tabular}
    \end{center}
\caption{Collection of all interaction terms with three LQ fields that result in a vanishing total weak hypercharge $Y$. The numbers in the table indicate the number of the corresponding LQ fields interacting in the vertex. The same combinations with all fields replaced by their anti-fields correspond to the Hermitian conjugates and are also valid solutions.  }
\label{tab:triple}
\end{table}


However, not all of these combinations can be implemented. Since the Lagrangian is symmetric under the exchange of identical bosons and the color terms are totally anti-symmetric, the $SU(2)_L$ part needs to be anti-symmetric for identical bosons as well. This is not satisfied by $Y_{112}, Y_{11\tilde{2}}, Y_{\tilde{2} \tilde{2} \tilde{2}}, A_{\tilde{2}\tilde{2}3}$ in Table~\ref{tab:triple}. Hence, the Lagrangian is composed of the terms~\cite{Kovalenko:2002eh, Klapdor-Kleingrothaus:2002rvk, Arnold:2012sd, Hambye:2017qix}


\begin{align}
    \begin{aligned}
        \mathcal{L}_{3 \Phi} 
        &= \phantom{12} A_{1\tilde{2}\tilde{2}} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right)
        + A_{\tilde{1}2\tilde{2}} \ \Phi_{\tilde{1}, c_1} \left(\Phi_{2, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right) \\
        &\phantom{12}+ Y_{1 \tilde{1}2} \ \Phi_{1, c_1} \Phi_{\tilde{1}, c_2} \left( \Phi_{2, c_3}^\intercal i \sigma_2 H \right)
        + Y_{123} \ \Phi_{1, c_1} \left(H^\dagger \left( \sigma \cdot \Phi_{3, c_3} \right) \Phi_{2, c_2}\right) \\
        &\phantom{12}+ Y_{1\tilde{2}3} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i \sigma_2 \left( \sigma \cdot \Phi_{3, c_3} \right) H\right)
        + Y_{\tilde{1}23} \ \Phi_{\tilde{1}, c_1} \left(\Phi_{2, c_2}^\intercal i \sigma_2 \left( \sigma \cdot \Phi_{3, c_3} \right) H\right)  \\
        &\phantom{12}+ Y_{233} \ \left(H^\dagger \sigma^I \Phi_{2, c_1}\right)\left( \Phi^J_{3, c_2} i \epsilon^{IJK} \Phi^K_{3, c_3}\right) \\
        &\phantom{12}+  Y_{\tilde{2}33} \ \left(\Phi_{\tilde{2}, c_1}^\intercal i \sigma_2 \sigma^I H\right) \left( \Phi^J_{3, c_2} i\epsilon^{IJK}\Phi^K_{3, c_3} \right) \\
        &\phantom{12}+ \text{h.c.} \,.& 
        \label{eq:LQ_triplet_interactions}
    \end{aligned}
\end{align}


The Levi-Civita tensors $\epsilon^{c_1 c_2 c_3}$ are omitted, such that i.e.~the first term would read $A_{1\tilde{2}\tilde{2}} \epsilon^{c_1c_2c_3} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right)$ in the full notation. 

\subsection{Quartic LQ Interactions ($\mathcal{L}_{4 \Phi}$)}
To get four-LQ interaction terms in the Lagrangian, one needs to combine two LQs and two anti-LQs, since


\begin{equation}
3 \otimes \overline{3} \otimes 3 \otimes \overline{3} = 1 \oplus 1 \oplus 8 \oplus 8 \oplus 8 \oplus 8 \oplus 10 \oplus \overline{10} \oplus 27
\label{eq:SU(3)_singlets}
\end{equation}
is the only tensor product of four $SU(3)_{c}$ fundamental representations $\left(3, \overline{3}\right)$ that contains a singlet. Trivial combinations of LQ fields that contribute to the four-LQ Lagrangian are of the type
\begin{equation}
\begin{aligned}
Y^{(1)}_{a} \left(\Phi^\dagger_{a, c_1} \Phi_{a, c_1}\right) \left( \Phi^\dagger_{a, c_2} \Phi_{a, c_2} \right)\,, \\
Y^{(1)}_{ab} \left(\Phi^\dagger_{a, c_1} \Phi_{a, c_1}\right) \left( \Phi^\dagger_{b, c_2} \Phi_{b, c_2} \right)\,,
\end{aligned}
\label{eq:obviouscombination}
\end{equation}


where $a \neq b \in \left\{1,\tilde{1}, 2, \tilde{2}, 3 \right\}$. All additional combinations that result in a vanishing total weak hypercharge $Y$ are given in Tab.~\ref{tab:quartic}. 


